def findValidPair(s: str) -> str:
    from collections import Counter
    count = Counter(s)
    for i in range(len(s) - 1):
        if s[i] != s[i + 1]:
            first = int(s[i])
            second = int(s[i + 1])
            if count[s[i]] == first and count[s[i + 1]] == second:
                return s[i] + s[i + 1]
    return ""

def maxDifference(s: str) -> int:
    from collections import Counter
    frequencies = Counter(s)
    max_odd = float('-inf')
    min_even = float('inf')
    for freq in frequencies.values():
        if freq % 2 == 1:
            max_odd = max(max_odd, freq)
        else:
            min_even = min(min_even, freq)
    return max_odd - min_even

