def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict

    count = defaultdict(int)
    n = len(nums)

    # Count the occurrences of each number in each subarray of size k
    for i in range(n - k + 1):
        seen = set()
        for j in range(k):
            if nums[i + j] not in seen:
                count[nums[i + j]] += 1
                seen.add(nums[i + j])

    # Find the largest integer that appears in exactly one subarray
    largest = -1
    for num, c in count.items():
        if c == 1:
            largest = max(largest, num)

    return largest

