def minCost(n: int, cost: List[List[int]]) -> int:
    # Initialize a DP table to keep track of costs
    dp = [[float('inf')] * 3 for _ in range(n)]

    # Fill the first house costs
    for j in range(3):
        dp[0][j] = cost[0][j]

    # Fill the DP table while ensuring no two adjacent houses have the same color
    for i in range(1, n):
        for j in range(3):
            for k in range(3):
                if j != k:
                    dp[i][j] = min(dp[i][j], dp[i-1][k] + cost[i][j])

    # To handle the equidistant constraint, we will perform a second DP fill
    final_min_cost = float('inf')
    for j in range(3):
        # Calculate the cost while using the opposite house for equidistant checking
        dp_opposite = [[float('inf')] * 3 for _ in range(n)]
        for i in range(n):
            for k in range(3):
                if (i < n // 2 and j != k) or (i >= n // 2 and j != (2 - k)):
                    dp_opposite[n - 1 - i][k] = min(dp_opposite[n - 1 - i][k], dp[i][j])

        # Gather minimum cost from the second DP
        for k in range(3):
            if n // 2 >= 1 and j != (2 - k):
                final_min_cost = min(final_min_cost, dp_opposite[n-1][k])

    return final_min_cost

from typing import List

def countMentions(numberOfUsers: int, events: List[List[str]]) -> List[int]:
    mentions = [0] * numberOfUsers
    online_status = [True] * numberOfUsers
    offline_until = [0] * numberOfUsers

    for event in events:
        event_type, timestamp, *details = event
        timestamp = int(timestamp)

        if event_type == "OFFLINE":
            user_id = int(details[0][2:])  # Extract user ID from 'id<number>'
            online_status[user_id] = False
            offline_until[user_id] = timestamp + 60

        elif event_type == "MESSAGE":
            # Process offline users first
            for user_id in range(numberOfUsers):
                if timestamp >= offline_until[user_id]:
                    online_status[user_id] = True

            mentions_string = details[0]
            if mentions_string == "ALL":
                for i in range(numberOfUsers):
                    mentions[i] += 1
            elif mentions_string == "HERE":
                for i in range(numberOfUsers):
                    if online_status[i]:
                        mentions[i] += 1
            else:
                for mention in mentions_string.split():
                    if mention.startswith('id'):
                        user_id = int(mention[2:])  # Extract user ID from 'id<number>'
                        mentions[user_id] += 1

    return mentions
